import{_ as d,o as e,c as o,ag as r}from"./chunks/framework.C9sp7nFj.js";const h=JSON.parse('{"title":"MovLOffsetC 直线偏移指令（常量版）","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovLOffsetC.md","filePath":"3. 指令/1. 运动指令/MovLOffsetC.md","lastUpdated":1778862643000}'),a={name:"3. 指令/1. 运动指令/MovLOffsetC.md"};function c(O,t,s,f,n,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="movloffsetc-直线偏移指令-常量版" tabindex="-1">MovLOffsetC 直线偏移指令（常量版） <a class="header-anchor" href="#movloffsetc-直线偏移指令-常量版" aria-label="Permalink to &quot;MovLOffsetC 直线偏移指令（常量版）&quot;">​</a></h1><p>直线偏移运动指令（常量版）。该指令的功能与 <code>MovLOffset</code> 一致，唯一的区别在于：<code>MovLOffset</code> 使用 <code>DCPOS</code> 类型变量作为增量，而 <strong>MovLOffsetC</strong> 直接使用 <strong>X、Y、Z、A 四个实数（real）常量</strong>作为位置增量。这使得开发者可以直接在指令中输入具体的数值，而无需预先定义位置变量。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovLOffsetC(RP, TPX, TPY, TPZ, TPA, T, Tool, Coord, [V], [B], [C], [PayLoad], O, [DO])</p><p>MovLOffsetC(参考点, X偏移点, Y偏移点, Z偏移点, A偏移点, 目标点, 工具, 坐标系, [速度], [平滑], [姿态], [负载], 姿态控制, [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>RP</td><td>APOS 或 CPOS 变量</td><td>坐标系下的基准参考点位置。</td><td>必填</td></tr><tr><td>TPX / TPY / TPZ / TPA</td><td>real 常量</td><td>执行指令时机器人在对应方向（X、Y、Z、A）上要移动的位置偏移数值。</td><td>必填</td></tr><tr><td>T</td><td>enum（COORD / TOOL）</td><td><code>COORD</code>：参考用户坐标系进行偏移。<br><code>TOOL</code>：参考工具坐标系进行偏移。</td><td>必填</td></tr><tr><td>Tool</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>必填</td></tr><tr><td>Coord</td><td>USERCOOR 变量</td><td>机器人执行该轨迹时使用的用户坐标系。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定机器人执行时的速度。在偏移指令中，通常 SPEED 变量中的 <code>per</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式（无过渡、相对、绝对、缺省）。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡半径或数值。</td><td>可选，默认 C100</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的负载参数。</td><td>可选，默认使用当前系统中设置的负载</td></tr><tr><td>O</td><td>enum（GOVRON / GOVROFF）</td><td>设置当前指令轨迹是否受全局速度倍率（Override）影响。</td><td>可选，默认 GOVRON</td></tr><tr><td>[DO]</td><td>string</td><td>指令执行完后触发的 IO 操作（如 <code>SetDO</code>、<code>PulseOut</code> 等）。目前支持：<code>SetDO</code>、<code>SetAO</code>、<code>SetSimDO</code>、<code>SetSimAO</code>、<code>PulseOut</code>、<code>PulseSimOut</code>、<code>SetDO8421</code>、<code>SetSimDO8421</code>、<code>SetDIEdge</code>、<code>SetSimDIEdge</code>。</td><td>可选</td></tr></tbody></table>',9)])])}const P=d(a,[["render",c]]);export{h as __pageData,P as default};
